/**
 * The migration engine: status, deploy, dev, push and reset on top of a
 * dialect, an executor and a folder of migration files. It prints nothing;
 * the CLI and the studio render what it returns and the hooks it calls.
 */
import { KastorError } from '../core/errors';
import type { Adapter, AppliedMigration, Dialect, Executor, MigrationOpLike, SchemaIR } from '../core/ir';
import {
  diffSchemas,
  findColumnRenameCandidates,
  findTableRenameCandidates,
  type DiffResult,
  type Rename,
  type RenameCandidate,
} from './diff';
import { nextId, readLock, readMigrations, renderMigration, suggestName, writeLock, writeMigration, type LocalMigration } from './files';
import { applyOp, rawSqlFor, type MigrationOp } from './ops';
import { splitStatements, stripLeadingComments } from './sql-split';

export const MIGRATIONS_TABLE = '_kastor_migrations';

export interface MigrationHooks {
  /** Called before each migration runs. */
  onApply?(migration: LocalMigration): void;
  /** Called after each migration ran and was recorded. */
  onApplied?(migration: LocalMigration, ms: number): void;
}

const isMigrationsTable = (name: string): boolean => name.toLowerCase() === MIGRATIONS_TABLE;

/** The live schema without kastor's own bookkeeping table. */
export async function introspect(adapter: Adapter): Promise<SchemaIR> {
  const schema = await adapter.dialect.introspect(adapter.executor);
  return { ...schema, tables: schema.tables.filter((t) => !isMigrationsTable(t.name)) };
}

export interface PlannedStep {
  op: MigrationOp;
  statements: string[];
}

/** Turns ops into DDL, handing every op the schema as it is after that op. */
export function planStatements(dialect: Pick<Dialect, 'name' | 'ddl'>, current: SchemaIR, ops: MigrationOp[]): PlannedStep[] {
  let state = current;
  const steps: PlannedStep[] = [];
  for (const op of ops) {
    state = applyOp(state, op);
    const statements = op.kind === 'raw' ? rawSqlFor(op, dialect.name) : dialect.ddl(op as unknown as MigrationOpLike, state);
    steps.push({ op, statements });
  }
  return steps;
}

/* ------------------------------------------------------------------------ */
/* Status                                                                    */
/* ------------------------------------------------------------------------ */

export interface MigrationStatus {
  local: LocalMigration[];
  applied: AppliedMigration[];
  /** Local migrations not applied yet, oldest first. */
  pending: LocalMigration[];
  /** Applied migrations whose file changed afterwards. */
  modified: Array<{ local: LocalMigration; applied: AppliedMigration }>;
  /** Applied migrations whose folder is gone. */
  missing: AppliedMigration[];
  /** Dialect written in the lock file, if any. */
  lockDialect?: string;
}

export async function status(adapter: Adapter, dir: string): Promise<MigrationStatus> {
  const { dialect, executor } = adapter;
  await dialect.migrationTable.ensure(executor);
  const applied = (await dialect.migrationTable.list(executor)).sort((a, b) => a.id.localeCompare(b.id));
  const local = readMigrations(dir);
  const byId = new Map(applied.map((a) => [a.id, a]));
  const localIds = new Set(local.map((m) => m.id));
  return {
    local,
    applied,
    pending: local.filter((m) => !byId.has(m.id)),
    modified: local.filter((m) => byId.has(m.id) && byId.get(m.id)!.checksum !== m.checksum).map((m) => ({ local: m, applied: byId.get(m.id)! })),
    missing: applied.filter((a) => !localIds.has(a.id)),
    lockDialect: readLock(dir),
  };
}

function checkLock(adapter: Adapter, st: MigrationStatus, dir: string): void {
  if (st.lockDialect && st.lockDialect !== adapter.dialect.name) {
    throw new KastorError('MIGRATION_FAILED', `The migrations in ${dir} were written for ${st.lockDialect}, but the config connects to ${adapter.dialect.name}.`, {
      hint: 'Point the config at the right database, or move the old migrations away and create new ones with kastor migrate dev.',
      meta: { lock: st.lockDialect, dialect: adapter.dialect.name },
    });
  }
}

function checkModified(st: MigrationStatus, dev: boolean): void {
  if (!st.modified.length) return;
  const ids = st.modified.map((m) => m.local.id);
  throw new KastorError('MIGRATION_DRIFT', `Migration${ids.length > 1 ? 's' : ''} ${ids.join(', ')} changed after ${ids.length > 1 ? 'they were' : 'it was'} applied.`, {
    hint: dev
      ? 'Restore the file from version control, or run kastor migrate reset to rebuild the development database from the files.'
      : 'Restore the file from version control. Applied migrations must not change; write a new migration instead.',
    meta: { migrations: ids },
  });
}

/* ------------------------------------------------------------------------ */
/* Apply                                                                     */
/* ------------------------------------------------------------------------ */

/**
 * Statements of a migration file. SQL files are written by `renderMigration`,
 * so the shared splitter (which understands its block markers) reads them;
 * databases without SQL bring their own `splitScript`.
 */
export function statementsOf(dialect: Pick<Dialect, 'name' | 'splitScript'>, sql: string): string[] {
  return dialect.name === 'mongodb' && dialect.splitScript ? dialect.splitScript(sql) : splitStatements(sql);
}

/** Runs one migration file and records it, inside a transaction where DDL is transactional. */
export async function applyMigration(adapter: Adapter, migration: LocalMigration): Promise<void> {
  const { dialect } = adapter;
  const statements = statementsOf(dialect, migration.sql);
  await runScript(adapter, statements, migration.id, async (exec) => {
    await dialect.migrationTable.record(exec, { id: migration.id, checksum: migration.checksum, appliedAt: new Date() });
  });
}

const FK_OFF = /^\s*PRAGMA\s+foreign_keys\s*=\s*(OFF|0|false)\b/i;

/**
 * Runs statements as one unit: inside a transaction where DDL is
 * transactional, statement by statement otherwise. SQLite table rebuilds need
 * foreign keys off, which only works outside a transaction, so they are turned
 * off around it and checked with `PRAGMA foreign_key_check` before commit.
 */
async function runScript(adapter: Adapter, statements: string[], label: string, after?: (exec: Executor) => Promise<void>): Promise<void> {
  const { dialect, executor } = adapter;
  const run = async (exec: Executor): Promise<void> => {
    await runStatements(exec, statements, label);
    if (fkOff) {
      const broken = await exec.query('PRAGMA foreign_key_check', []);
      if (broken.rows.length) {
        const first = broken.rows[0]!;
        throw new KastorError('MIGRATION_FAILED', `${label} leaves ${broken.rows.length} row(s) whose foreign key points nowhere, for example in ${String(first.table)} (to ${String(first.parent)}).`, {
          hint: 'Fix or delete those rows in the migration before the tables are rebuilt.',
          meta: { migration: label, rows: broken.rows.slice(0, 20) },
        });
      }
    }
    await after?.(exec);
  };
  const fkOff = dialect.name === 'sqlite' && statements.some((s) => FK_OFF.test(stripLeadingComments(s)));
  if (fkOff) await executor.query('PRAGMA foreign_keys = OFF', []);
  try {
    if (dialect.features.transactionalDdl && dialect.features.transactions) await executor.transaction(run);
    else await run(executor);
  } finally {
    if (fkOff) await executor.query('PRAGMA foreign_keys = ON', []);
  }
}

async function runStatements(exec: Executor, statements: string[], label: string): Promise<void> {
  for (let i = 0; i < statements.length; i++) {
    const sql = statements[i]!;
    try {
      await exec.query(sql, []);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new KastorError('MIGRATION_FAILED', `${label} failed at statement ${i + 1} of ${statements.length}: ${reason}`, {
        hint: 'Fix the SQL or the data it trips on, then run the command again. Databases without transactional DDL keep the statements that already ran.',
        meta: { migration: label, statement: sql, index: i },
        cause: error,
      });
    }
  }
}

/** Applies every pending migration. The deploy command for CI and production. */
export async function deploy(adapter: Adapter, dir: string, hooks: MigrationHooks = {}): Promise<{ applied: LocalMigration[]; status: MigrationStatus }> {
  const st = await status(adapter, dir);
  checkLock(adapter, st, dir);
  checkModified(st, false);
  const applied: LocalMigration[] = [];
  for (const m of st.pending) {
    hooks.onApply?.(m);
    const start = Date.now();
    await applyMigration(adapter, m);
    hooks.onApplied?.(m, Date.now() - start);
    applied.push(m);
  }
  return { applied, status: st };
}

/* ------------------------------------------------------------------------ */
/* Renames                                                                   */
/* ------------------------------------------------------------------------ */

export interface RenameResolution {
  renames: Rename[];
  /** Candidates nobody answered (no flag, no prompt). */
  unresolved: RenameCandidate[];
}

/**
 * Settles possible renames: `flags` first, then `ask` for each remaining
 * candidate (return the new name, or null for drop and create). Without `ask`
 * the remaining candidates come back as unresolved.
 */
export async function resolveRenames(
  live: SchemaIR,
  target: SchemaIR,
  flags: Rename[] = [],
  ask?: (candidate: RenameCandidate) => Promise<string | null>,
): Promise<RenameResolution> {
  const renames: Rename[] = [];
  const unresolved: RenameCandidate[] = [];
  const settle = async (candidates: RenameCandidate[], kind: 'table' | 'column'): Promise<void> => {
    const taken = new Set(renames.filter((r) => r.kind === kind).map((r) => `${r.table ?? ''}.${r.to}`));
    for (const cand of candidates) {
      const options = cand.to.filter((name) => !taken.has(`${cand.table ?? ''}.${name}`));
      if (!options.length) continue;
      if (!ask) {
        unresolved.push({ ...cand, to: options });
        continue;
      }
      const answer = await ask({ ...cand, to: options });
      if (answer) {
        renames.push({ kind, table: cand.table, from: cand.from, to: answer });
        taken.add(`${cand.table ?? ''}.${answer}`);
      }
    }
  };
  const tableFlags = flags.filter((f) => f.kind === 'table');
  renames.push(...tableFlags);
  const flaggedTables = new Set(tableFlags.map((f) => f.from));
  await settle(
    findTableRenameCandidates(live, target).filter((c) => !flaggedTables.has(c.from)),
    'table',
  );
  const columnFlags = flags.filter((f) => f.kind === 'column');
  renames.push(...columnFlags);
  const flaggedColumns = new Set(columnFlags.map((f) => `${f.table}.${f.from}`));
  const tableRenames = renames.filter((r) => r.kind === 'table');
  await settle(
    findColumnRenameCandidates(live, target, tableRenames).filter((c) => !flaggedColumns.has(`${c.table}.${c.from}`)),
    'column',
  );
  return { renames, unresolved };
}

/* ------------------------------------------------------------------------ */
/* Dev, push, reset                                                          */
/* ------------------------------------------------------------------------ */

export interface ChangeOptions {
  /** `--rename` answers. */
  renames?: Rename[];
  /** Interactive rename question; see `resolveRenames`. */
  askRename?: (candidate: RenameCandidate) => Promise<string | null>;
  /** Allow drops without asking. */
  acceptDataLoss?: boolean;
  /** Asked before writing destructive changes when `acceptDataLoss` is off; return false to stop. */
  confirmDataLoss?: (diff: DiffResult) => Promise<boolean>;
  /** Shown the planned changes before anything is written; return false to stop. */
  review?: (diff: DiffResult, steps: PlannedStep[]) => Promise<boolean>;
}

export interface DevOptions extends ChangeOptions, MigrationHooks {
  name?: string;
  createOnly?: boolean;
  /** kastor version, written in the file header. */
  version: string;
  /** Called once the new migration file is on disk, before it is applied. */
  onWritten?(migration: LocalMigration): void;
}

export type DevResult =
  | { kind: 'in-sync'; appliedPending: LocalMigration[] }
  | { kind: 'cancelled'; diff: DiffResult; appliedPending: LocalMigration[] }
  | { kind: 'created'; migration: LocalMigration; diff: DiffResult; steps: PlannedStep[]; applied: boolean; appliedPending: LocalMigration[] };

async function computeChanges(adapter: Adapter, target: SchemaIR, options: ChangeOptions): Promise<{ live: SchemaIR; diff: DiffResult; steps: PlannedStep[] } | null> {
  const live = await introspect(adapter);
  const { renames, unresolved } = await resolveRenames(live, target, options.renames ?? [], options.askRename);
  if (unresolved.length && !options.acceptDataLoss) {
    const c = unresolved[0]!;
    const what = c.kind === 'table' ? `table ${c.from}` : `column ${c.table}.${c.from}`;
    const flag = c.kind === 'table' ? `--rename ${c.from}:${c.to[0]}` : `--rename ${c.table}.${c.from}:${c.to[0]}`;
    throw new KastorError('MIGRATION_FAILED', `The ${what} is gone from the schema and ${c.to.join(' or ')} appeared. kastor cannot tell whether it was renamed.`, {
      hint: `If it was renamed, pass ${flag}. To drop it and lose its data, pass --accept-data-loss.`,
      meta: { unresolved },
    });
  }
  const diff = diffSchemas(live, target, { renames, dialect: adapter.dialect });
  if (!diff.ops.length) return null;
  const steps = planStatements(adapter.dialect, live, diff.ops);
  return { live, diff, steps };
}

async function gate(diff: DiffResult, steps: PlannedStep[], options: ChangeOptions): Promise<boolean> {
  if (options.review && !(await options.review(diff, steps))) return false;
  if (diff.destructive && !options.acceptDataLoss) {
    if (!options.confirmDataLoss) {
      throw new KastorError('MIGRATION_FAILED', 'These changes drop data and nobody confirmed them.', {
        hint: 'Run the command in a terminal to confirm, or pass --accept-data-loss.',
      });
    }
    if (!(await options.confirmDataLoss(diff))) return false;
  }
  return true;
}

/**
 * `migrate dev`: applies pending migrations, diffs the database against the
 * schema, writes a new migration file and applies it.
 */
export async function dev(adapter: Adapter, target: SchemaIR, dir: string, options: DevOptions): Promise<DevResult> {
  const st = await status(adapter, dir);
  checkLock(adapter, st, dir);
  checkModified(st, true);
  const appliedPending: LocalMigration[] = [];
  for (const m of st.pending) {
    options.onApply?.(m);
    const start = Date.now();
    await applyMigration(adapter, m);
    options.onApplied?.(m, Date.now() - start);
    appliedPending.push(m);
  }
  const changes = await computeChanges(adapter, target, options);
  if (!changes) return { kind: 'in-sync', appliedPending };
  const { diff, steps } = changes;
  if (!(await gate(diff, steps, options))) return { kind: 'cancelled', diff, appliedPending };
  const id = nextId(dir, options.name ? options.name : suggestName(diff.ops));
  const sql = renderMigration({ id, dialect: adapter.dialect.name, version: options.version, steps, warnings: diff.warnings });
  const migration = writeMigration(dir, id, sql);
  if (!st.lockDialect) writeLock(dir, adapter.dialect.name);
  options.onWritten?.(migration);
  if (options.createOnly) return { kind: 'created', migration, diff, steps, applied: false, appliedPending };
  options.onApply?.(migration);
  const start = Date.now();
  await applyMigration(adapter, migration);
  options.onApplied?.(migration, Date.now() - start);
  return { kind: 'created', migration, diff, steps, applied: true, appliedPending };
}

export type PushResult = { kind: 'in-sync' } | { kind: 'cancelled'; diff: DiffResult } | { kind: 'pushed'; diff: DiffResult; steps: PlannedStep[] };

/** `db push`: makes the database match the schema without writing files. */
export async function push(adapter: Adapter, target: SchemaIR, options: ChangeOptions = {}): Promise<PushResult> {
  const changes = await computeChanges(adapter, target, options);
  if (!changes) return { kind: 'in-sync' };
  const { diff, steps } = changes;
  if (!(await gate(diff, steps, options))) return { kind: 'cancelled', diff };
  await runScript(adapter, steps.flatMap((s) => s.statements), 'db push');
  return { kind: 'pushed', diff, steps };
}

/** Drops every table and enum kastor can see, including the bookkeeping table. */
export async function dropEverything(adapter: Adapter): Promise<PlannedStep[]> {
  const live = await adapter.dialect.introspect(adapter.executor);
  const { ops } = diffSchemas(live, { tables: [] }, { dialect: adapter.dialect });
  const steps = planStatements(adapter.dialect, live, ops);
  await runScript(adapter, steps.flatMap((s) => s.statements), 'reset');
  // Some dialects hide the bookkeeping table from introspection: make sure it
  // exists, then drop it, so the history starts over too.
  if (!live.tables.some((t) => isMigrationsTable(t.name))) {
    const { dialect, executor } = adapter;
    await dialect.migrationTable.ensure(executor);
    const op: MigrationOp = { kind: 'dropTable', table: MIGRATIONS_TABLE };
    const drop = dialect.ddl(op as unknown as MigrationOpLike, { tables: [] });
    await runStatements(executor, drop, 'reset');
    steps.push({ op, statements: drop });
  }
  return steps;
}

/** `migrate reset`: drops everything and applies every migration from scratch. */
export async function reset(adapter: Adapter, dir: string, hooks: MigrationHooks = {}): Promise<{ dropped: PlannedStep[]; applied: LocalMigration[] }> {
  const dropped = await dropEverything(adapter);
  const { applied } = await deploy(adapter, dir, hooks);
  return { dropped, applied };
}

/** Differences between the live database and the schema, for `doctor` and `migrate status`. */
export async function drift(adapter: Adapter, target: SchemaIR): Promise<DiffResult> {
  const live = await introspect(adapter);
  return diffSchemas(live, target, { dialect: adapter.dialect });
}

src/migrate/files.ts:
/**
 * Migration files on disk: `kastor/migrations/<timestamp>_<name>/migration.sql`,
 * readable SQL with a commented header, and a lock file that records which
 * database the folder targets.
 */
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { describeOp, isDestructive, type MigrationOp } from './ops';
import { formatStatement } from './sql-split';
import type { DiffWarning } from './diff';

export const MIGRATION_FILE = 'migration.sql';
export const LOCK_FILE = 'migration_lock.toml';

export interface LocalMigration {
  /** Folder name, `<timestamp>_<name>`. */
  id: string;
  name: string;
  dir: string;
  file: string;
  sql: string;
  checksum: string;
}

/** sha256 of the file with line endings normalized, so a checkout with CRLF matches. */
export function checksum(sql: string): string {
  return createHash('sha256').update(sql.replace(/\r\n?/g, '\n'), 'utf8').digest('hex');
}

/** `20261013224700`, UTC. */
export function timestamp(date = new Date()): string {
  const p = (n: number, w = 2): string => String(n).padStart(w, '0');
  return `${date.getUTCFullYear()}${p(date.getUTCMonth() + 1)}${p(date.getUTCDate())}${p(date.getUTCHours())}${p(date.getUTCMinutes())}${p(date.getUTCSeconds())}`;
}

/** Lower snake case, letters, digits and underscores, at most 60 characters. */
export function sanitizeName(name: string): string {
  const clean = name
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 60)
    .replace(/_+$/, '');
  return clean || 'migration';
}

/** A short name that says what the migration does, used when `--name` is left out. */
export function suggestName(ops: MigrationOp[]): string {
  if (!ops.length) return 'empty';
  const created = ops.filter((o) => o.kind === 'createTable').map((o) => (o.kind === 'createTable' ? o.table.name : ''));
  if (created.length && created.length === ops.filter((o) => o.kind !== 'createIndex' && o.kind !== 'createEnum' && o.kind !== 'addForeignKey').length) {
    return sanitizeName(`create_${created.slice(0, 3).join('_')}${created.length > 3 ? '_and_more' : ''}`);
  }
  const first = ops.find((o) => o.kind !== 'createIndex' && o.kind !== 'createEnum') ?? ops[0]!;
  const base = (() => {
    switch (first.kind) {
      case 'addColumn':
        return `add_${first.table}_${first.column.name}`;
      case 'dropColumn':
        return `drop_${first.table}_${first.column}`;
      case 'alterColumn':
        return `alter_${first.table}_${first.column}`;
      case 'renameColumn':
        return `rename_${first.table}_${first.from}`;
      case 'renameTable':
        return `rename_${first.from}`;
      case 'dropTable':
        return `drop_${first.table}`;
      case 'createTable':
        return `create_${first.table.name}`;
      case 'createIndex':
      case 'dropIndex':
        return `${first.kind === 'createIndex' ? 'add' : 'drop'}_index_${first.table}`;
      case 'addForeignKey':
      case 'dropForeignKey':
        return `${first.kind === 'addForeignKey' ? 'add' : 'drop'}_fk_${first.table}`;
      case 'alterEnum':
        return `alter_enum_${first.name}`;
      case 'createEnum':
      case 'dropEnum':
        return `${first.kind === 'createEnum' ? 'create' : 'drop'}_enum_${first.enum.name}`;
      default:
        return 'custom';
    }
  })();
  return sanitizeName(ops.length > 1 ? `${base}_and_more` : base);
}

export interface RenderInput {
  id: string;
  dialect: string;
  version: string;
  /** Statements per op, in op order. */
  steps: Array<{ op: MigrationOp; statements: string[] }>;
  warnings?: DiffWarning[];
  date?: Date;
}

/** The migration.sql text: a header with a summary, then one commented block per op. */
export function renderMigration(input: RenderInput): string {
  const date = (input.date ?? new Date()).toISOString().replace('T', ' ').replace(/\.\d+Z$/, ' UTC');
  const lines: string[] = [
    `-- Migration ${input.id}`,
    `-- Written by kastor ${input.version} for ${input.dialect} on ${date}.`,
    '-- Applied by `kastor migrate deploy`. Edit it before it is applied if you need to;',
    '-- after that, the checksum in _kastor_migrations must keep matching.',
  ];
  if (input.steps.length) {
    lines.push('--', '-- Changes:');
    for (const { op } of input.steps) lines.push(`--   ${symbolFor(op)} ${describeOp(op)}${isDestructive(op) ? '  [data loss]' : ''}`);
  }
  if (input.warnings?.length) {
    lines.push('--', '-- Warnings:');
    for (const w of input.warnings) lines.push(`--   ${w.message}`);
  }
  lines.push('');
  for (const { op, statements } of input.steps) {
    if (!statements.length) continue;
    lines.push(`-- ${describeOp(op)}`);
    for (const s of statements) lines.push(formatStatement(s));
    lines.push('');
  }
  if (!input.steps.some((s) => s.statements.length)) lines.push('-- This migration is empty. Add your own SQL below.', '');
  return lines.join('\n');
}

export function symbolFor(op: MigrationOp): string {
  if (op.kind.startsWith('create') || op.kind.startsWith('add')) return '+';
  if (op.kind.startsWith('drop')) return '-';
  if (op.kind.startsWith('rename')) return '>';
  return '~';
}

/** Lists the migrations in a folder, oldest first. */
export function readMigrations(dir: string): LocalMigration[] {
  if (!existsSync(dir)) return [];
  const out: LocalMigration[] = [];
  for (const entry of readdirSync(dir).sort()) {
    const path = join(dir, entry);
    if (!statSync(path).isDirectory()) continue;
    const m = /^(\d{14})_(.+)$/.exec(entry);
    if (!m) continue;
    const file = join(path, MIGRATION_FILE);
    if (!existsSync(file)) continue;
    const sql = readFileSync(file, 'utf8');
    out.push({ id: entry, name: m[2]!, dir: path, file, sql, checksum: checksum(sql) });
  }
  return out;
}

/** A new folder id after every existing one, even when two run in the same second. */
export function nextId(dir: string, name: string, date = new Date()): string {
  const existing = readMigrations(dir).map((m) => m.id.slice(0, 14));
  let stamp = timestamp(date);
  const last = existing.at(-1);
  if (last && last >= stamp) stamp = bumpStamp(last);
  return `${stamp}_${sanitizeName(name)}`;
}

function bumpStamp(stamp: string): string {
  const d = new Date(Date.UTC(+stamp.slice(0, 4), +stamp.slice(4, 6) - 1, +stamp.slice(6, 8), +stamp.slice(8, 10), +stamp.slice(10, 12), +stamp.slice(12, 14) + 1));
  return timestamp(d);
}

export function writeMigration(dir: string, id: string, sql: string): LocalMigration {
  const folder = join(dir, id);
  mkdirSync(folder, { recursive: true });
  const file = join(folder, MIGRATION_FILE);
  writeFileSync(file, sql, 'utf8');
  return { id, name: id.slice(15), dir: folder, file, sql, checksum: checksum(sql) };
}

/** Reads the dialect recorded in the lock file, if any. */
export function readLock(dir: string): string | undefined {
  const file = join(dir, LOCK_FILE);
  if (!existsSync(file)) return undefined;
  const m = /^\s*dialect\s*=\s*"([^"]+)"/m.exec(readFileSync(file, 'utf8'));
  return m?.[1];
}

export function writeLock(dir: string, dialect: string): void {
  mkdirSync(dir, { recursive: true });
  writeFileSync(
    join(dir, LOCK_FILE),
    `# Written by kastor. The migrations in this folder are SQL for this database.\n# Commit this file with the migrations.\ndialect = "${dialect}"\n`,
    'utf8',
  );
}

src/migrate/ops.ts:
/**
 * Migration operations: the neutral steps a migration is made of.
 *
 * The diff engine (`src/migrate/diff.ts`) turns two SchemaIR snapshots into an
 * ordered list of these operations, and every dialect turns one operation into
 * DDL statements with `dialect.ddl(op, schema)`.
 *
 * Contract for dialect authors:
 * - `ddl(op, schema)` returns zero or more complete statements without a
 *   trailing semicolon. Return `[]` for operations that mean nothing to the
 *   dialect, for example `createEnum` where enums live on the column itself
 *   (`features.namedEnums === false`).
 * - `schema` is the state of the database AFTER the operation is applied (see
 *   `applyOp`). A dialect that rebuilds a table to change it (SQLite) reads the
 *   full target table from it.
 * - `createTable` creates the table with its columns, primary key, foreign keys
 *   (`table.foreignKeys`) and indexes (`table.indexes`, as CREATE INDEX
 *   statements after CREATE TABLE). The diff engine orders tables so referenced
 *   tables come first; foreign keys inside a cycle are left out of the
 *   `createTable` op and follow as `addForeignKey` once both tables exist.
 * - Unique constraints are indexes with `unique: true`.
 * - Every name in an op is a database name (after `.map()`).
 * - Statements may contain semicolons of their own (procedural blocks); the
 *   migration file writer marks them so they are read back as one statement.
 */
import type { ColumnIR, EnumIR, ForeignKeyIR, IndexIR, SchemaIR, TableIR } from '../core/ir';

export interface CreateTableOp {
  kind: 'createTable';
  table: TableIR;
}

export interface DropTableOp {
  kind: 'dropTable';
  table: string;
  /** The table as it was, for comments, warnings and dialects that need it. */
  previous?: TableIR;
}

export interface RenameTableOp {
  kind: 'renameTable';
  from: string;
  to: string;
}

export interface AddColumnOp {
  kind: 'addColumn';
  table: string;
  column: ColumnIR;
}

export interface DropColumnOp {
  kind: 'dropColumn';
  table: string;
  column: string;
  previous?: ColumnIR;
}

export interface RenameColumnOp {
  kind: 'renameColumn';
  table: string;
  from: string;
  to: string;
}

export interface AlterColumnOp {
  kind: 'alterColumn';
  table: string;
  column: string;
  from: ColumnIR;
  to: ColumnIR;
  /** Which aspects changed. A dialect may emit one statement per aspect. */
  changes: { type: boolean; nullable: boolean; default: boolean };
}

export interface CreateIndexOp {
  kind: 'createIndex';
  table: string;
  index: IndexIR;
}

export interface DropIndexOp {
  kind: 'dropIndex';
  table: string;
  index: IndexIR;
}

export interface AddForeignKeyOp {
  kind: 'addForeignKey';
  table: string;
  foreignKey: ForeignKeyIR;
}

export interface DropForeignKeyOp {
  kind: 'dropForeignKey';
  table: string;
  foreignKey: ForeignKeyIR;
}

export interface CreateEnumOp {
  kind: 'createEnum';
  enum: EnumIR;
}

export interface DropEnumOp {
  kind: 'dropEnum';
  enum: EnumIR;
}

/**
 * Changes the values of a named enum. Columns that use the enum are listed so
 * a dialect that has to recreate the type (to remove values) can convert them.
 */
export interface AlterEnumOp {
  kind: 'alterEnum';
  name: string;
  from: string[];
  to: string[];
  /** Values in `to` but not in `from`, in target order. */
  added: string[];
  /** Values in `from` but not in `to`. Removing values is destructive. */
  removed: string[];
  /** Columns typed with this enum, as `{ table, column }` database names. */
  columns: Array<{ table: string; column: string }>;
}

export interface RawOp {
  kind: 'raw';
  /** One SQL string for every dialect, or one per dialect name. */
  sql: string | Partial<Record<string, string>>;
  comment?: string;
}

export type MigrationOp =
  | CreateTableOp
  | DropTableOp
  | RenameTableOp
  | AddColumnOp
  | DropColumnOp
  | RenameColumnOp
  | AlterColumnOp
  | CreateIndexOp
  | DropIndexOp
  | AddForeignKeyOp
  | DropForeignKeyOp
  | CreateEnumOp
  | DropEnumOp
  | AlterEnumOp
  | RawOp;

export type MigrationOpKind = MigrationOp['kind'];

/** Statements of a raw op for one dialect. */
export function rawSqlFor(op: RawOp, dialect: string): string[] {
  const sql = typeof op.sql === 'string' ? op.sql : op.sql[dialect];
  return sql ? [sql] : [];
}

/** True when the op can lose data: dropping tables, columns or enum values, or narrowing a column. */
export function isDestructive(op: MigrationOp): boolean {
  switch (op.kind) {
    case 'dropTable':
    case 'dropColumn':
      return true;
    case 'alterEnum':
      return op.removed.length > 0;
    case 'alterColumn':
      return op.changes.type && !isWidening(op.from, op.to);
    default:
      return false;
  }
}

/** Type changes that never lose data. */
export function isWidening(from: ColumnIR, to: ColumnIR): boolean {
  if (from.type === to.type) {
    if (from.type === 'string') return (to.length ?? 255) >= (from.length ?? 255);
    if (from.type === 'decimal') {
      const fp = from.precision ?? 0;
      const fs = from.scale ?? 0;
      const tp = to.precision ?? Infinity;
      const ts = to.scale ?? 0;
      return ts >= fs && tp - ts >= fp - fs;
    }
    if (from.type === 'enum') return (from.enumValues ?? []).every((v) => (to.enumValues ?? []).includes(v));
    return true;
  }
  const safe: Record<string, string[]> = {
    int: ['bigint', 'float', 'decimal', 'string', 'text'],
    bigint: ['decimal', 'string', 'text'],
    float: ['string', 'text'],
    decimal: ['string', 'text'],
    string: ['text'],
    enum: ['string', 'text'],
    uuid: ['string', 'text'],
    boolean: ['string', 'text'],
    date: ['datetime', 'string', 'text'],
    time: ['string', 'text'],
  };
  if (to.type === 'string' && to.length !== undefined && from.type !== 'enum') return false;
  return safe[from.type]?.includes(to.type) ?? false;
}

/** A one line, human friendly description of an op, used in files and terminal output. */
export function describeOp(op: MigrationOp): string {
  switch (op.kind) {
    case 'createTable':
      return `Create table ${op.table.name}`;
    case 'dropTable':
      return `Drop table ${op.table}`;
    case 'renameTable':
      return `Rename table ${op.from} to ${op.to}`;
    case 'addColumn':
      return `Add column ${op.table}.${op.column.name}`;
    case 'dropColumn':
      return `Drop column ${op.table}.${op.column}`;
    case 'renameColumn':
      return `Rename column ${op.table}.${op.from} to ${op.to}`;
    case 'alterColumn': {
      const parts: string[] = [];
      if (op.changes.type) parts.push(`type ${columnTypeLabel(op.from)} to ${columnTypeLabel(op.to)}`);
      if (op.changes.nullable) parts.push(op.to.nullable ? 'make nullable' : 'make required');
      if (op.changes.default) parts.push(op.to.default ? `default ${defaultLabel(op.to)}` : 'drop default');
      return `Alter column ${op.table}.${op.column}: ${parts.join(', ')}`;
    }
    case 'createIndex':
      return `Create ${op.index.unique ? 'unique index' : 'index'} ${op.index.name} on ${op.table} (${op.index.columns.join(', ')})`;
    case 'dropIndex':
      return `Drop ${op.index.unique ? 'unique index' : 'index'} ${op.index.name} on ${op.table}`;
    case 'addForeignKey':
      return `Add foreign key ${op.foreignKey.name} on ${op.table} (${op.foreignKey.columns.join(', ')}) to ${op.foreignKey.refTable}`;
    case 'dropForeignKey':
      return `Drop foreign key ${op.foreignKey.name} on ${op.table}`;
    case 'createEnum':
      return `Create enum ${op.enum.name} (${op.enum.values.join(', ')})`;
    case 'dropEnum':
      return `Drop enum ${op.enum.name}`;
    case 'alterEnum': {
      const parts: string[] = [];
      if (op.added.length) parts.push(`add ${op.added.join(', ')}`);
      if (op.removed.length) parts.push(`remove ${op.removed.join(', ')}`);
      if (!parts.length) parts.push('reorder values');
      return `Alter enum ${op.name}: ${parts.join('; ')}`;
    }
    case 'raw':
      return op.comment ?? 'Custom SQL';
  }
}

/** `string(255)`, `decimal(10, 2)`, `enum(a, b)`, with `?` for nullable. */
export function columnTypeLabel(col: ColumnIR): string {
  let label: string = col.type;
  if (col.nativeType) label = col.nativeType;
  else if (col.type === 'string' && col.length !== undefined) label = `string(${col.length})`;
  else if (col.type === 'decimal' && col.precision !== undefined) label = `decimal(${col.precision}${col.scale !== undefined ? `, ${col.scale}` : ''})`;
  else if (col.type === 'enum' && col.enumValues) label = `enum(${col.enumValues.join(', ')})`;
  return label;
}

export function defaultLabel(col: ColumnIR): string {
  const d = col.default;
  if (!d) return 'none';
  switch (d.kind) {
    case 'now':
      return 'now()';
    case 'random':
      return 'random uuid';
    case 'autoincrement':
      return 'autoincrement';
    case 'sql':
      return String(d.value);
    default:
      return JSON.stringify(d.value);
  }
}

const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

/**
 * Applies one op to a schema snapshot and returns the new snapshot (the input
 * is not changed). The migration engine passes the result to `dialect.ddl` so
 * a dialect always sees the target state of the table it changes.
 */
export function applyOp(schema: SchemaIR, op: MigrationOp): SchemaIR {
  const next = clone(schema);
  next.tables ??= [];
  const table = (name: string): TableIR => {
    const t = next.tables.find((x) => x.name === name);
    if (!t) throw new Error(`applyOp: table ${name} does not exist`);
    return t;
  };
  const renameIn = (list: string[], from: string, to: string): string[] => list.map((c) => (c === from ? to : c));
  switch (op.kind) {
    case 'createTable':
      next.tables = next.tables.filter((t) => t.name !== op.table.name);
      next.tables.push(clone(op.table));
      break;
    case 'dropTable':
      next.tables = next.tables.filter((t) => t.name !== op.table);
      break;
    case 'renameTable':
      for (const t of next.tables) {
        if (t.name === op.from) t.name = op.to;
        for (const fk of t.foreignKeys) if (fk.refTable === op.from) fk.refTable = op.to;
      }
      for (const t of next.tables) for (const c of t.columns) if (c.type === 'enum' && !c.enumName && t.name === op.to) c.enumName = `${op.from}_${c.name}`;
      break;
    case 'addColumn':
      table(op.table).columns.push(clone(op.column));
      break;
    case 'dropColumn': {
      const t = table(op.table);
      t.columns = t.columns.filter((c) => c.name !== op.column);
      t.primaryKey = t.primaryKey.filter((c) => c !== op.column);
      t.indexes = t.indexes.filter((i) => !i.columns.includes(op.column));
      t.foreignKeys = t.foreignKeys.filter((f) => !f.columns.includes(op.column));
      break;
    }
    case 'renameColumn': {
      const t = table(op.table);
      for (const c of t.columns) if (c.name === op.from) c.name = op.to;
      t.primaryKey = renameIn(t.primaryKey, op.from, op.to);
      for (const i of t.indexes) i.columns = renameIn(i.columns, op.from, op.to);
      for (const f of t.foreignKeys) f.columns = renameIn(f.columns, op.from, op.to);
      for (const other of next.tables) for (const f of other.foreignKeys) if (f.refTable === op.table) f.refColumns = renameIn(f.refColumns, op.from, op.to);
      break;
    }
    case 'alterColumn': {
      const t = table(op.table);
      t.columns = t.columns.map((c) => (c.name === op.column ? clone(op.to) : c));
      break;
    }
    case 'createIndex':
      table(op.table).indexes.push(clone(op.index));
      break;
    case 'dropIndex': {
      const t = table(op.table);
      t.indexes = t.indexes.filter((i) => i.name !== op.index.name);
      break;
    }
    case 'addForeignKey':
      table(op.table).foreignKeys.push(clone(op.foreignKey));
      break;
    case 'dropForeignKey': {
      const t = table(op.table);
      t.foreignKeys = t.foreignKeys.filter((f) => f.name !== op.foreignKey.name);
      break;
    }
    case 'createEnum':
      next.enums = [...(next.enums ?? []).filter((e) => e.name !== op.enum.name), clone(op.enum)];
      break;
    case 'dropEnum':
      next.enums = (next.enums ?? []).filter((e) => e.name !== op.enum.name);
      break;
    case 'alterEnum':
      next.enums = (next.enums ?? []).map((e) => (e.name === op.name ? { name: e.name, values: [...op.to] } : e));
      for (const ref of op.columns) {
        const col = next.tables.find((t) => t.name === ref.table)?.columns.find((c) => c.name === ref.column);
        if (col) col.enumValues = [...op.to];
      }
      break;
    case 'raw':
      break;
  }
  return next;
}

src/migrate/sql-split.ts:
/**
 * Splits a migration file into statements, and writes statements back.
 *
 * Statements end with `;` outside of strings, quoted identifiers, comments and
 * PostgreSQL dollar quoted bodies. Procedural blocks (Oracle PL/SQL, SQL Server
 * batches) contain semicolons of their own, so they are written after a
 * `-- kastor:block` line and closed by a line holding only `/` (or `GO`), the
 * usual convention of the vendor tools. A statement that starts with `BEGIN` or
 * `DECLARE` is a block too.
 */
export const BLOCK_MARKER = '-- kastor:block';

export function splitStatements(sql: string): string[] {
  const out: string[] = [];
  const text = sql.replace(/\r\n?/g, '\n');
  let current = '';
  let block = false;
  let i = 0;
  const push = (): void => {
    const stmt = stripLeadingComments(current).trim();
    if (stmt) out.push(stmt);
    current = '';
    block = false;
  };
  while (i < text.length) {
    const ch = text[i]!;
    if (i === 0 || text[i - 1] === '\n') {
      const end = text.indexOf('\n', i);
      const stop = end === -1 ? text.length : end;
      const trimmed = text.slice(i, stop).trim();
      if (trimmed === '/' || /^go$/i.test(trimmed)) {
        push();
        i = stop + 1;
        continue;
      }
      if (trimmed === BLOCK_MARKER) {
        if (current.trim() && !block) push();
        block = true;
        i = stop + 1;
        continue;
      }
      if (!stripLeadingComments(current).trim() && /^(begin|declare)\b/i.test(trimmed)) block = true;
    }
    if (ch === '-' && text[i + 1] === '-') {
      const end = text.indexOf('\n', i);
      const stop = end === -1 ? text.length : end;
      current += text.slice(i, stop);
      i = stop;
      continue;
    }
    if (ch === '/' && text[i + 1] === '*') {
      const end = text.indexOf('*/', i + 2);
      const stop = end === -1 ? text.length : end + 2;
      current += text.slice(i, stop);
      i = stop;
      continue;
    }
    if (ch === "'" || ch === '"' || ch === '`' || ch === '[') {
      const close = ch === '[' ? ']' : ch;
      let j = i + 1;
      while (j < text.length) {
        if (text[j] === close) {
          if (text[j + 1] === close) {
            j += 2;
            continue;
          }
          break;
        }
        j++;
      }
      current += text.slice(i, j + 1);
      i = j + 1;
      continue;
    }
    if (ch === '$') {
      const m = /^\$([A-Za-z_][A-Za-z0-9_]*)?\$/.exec(text.slice(i, i + 64));
      if (m && !/[A-Za-z0-9_]/.test(text[i - 1] ?? '')) {
        const tag = m[0];
        const end = text.indexOf(tag, i + tag.length);
        const stop = end === -1 ? text.length : end + tag.length;
        current += text.slice(i, stop);
        i = stop;
        continue;
      }
    }
    if (ch === ';' && !block) {
      push();
      i++;
      continue;
    }
    current += ch;
    i++;
  }
  push();
  return out;
}

/** True when a statement must be written as a block (it has its own semicolons). */
export function isBlockStatement(stmt: string): boolean {
  if (/^\s*(begin|declare)\b/i.test(stmt)) return true;
  return splitStatements(stmt.trim().replace(/;\s*$/, '')).length > 1;
}

/** Writes one statement in the form `splitStatements` reads back. */
export function formatStatement(stmt: string): string {
  const s = stmt.trim();
  if (isBlockStatement(s)) return `${BLOCK_MARKER}\n${s}\n/`;
  return `${s.replace(/;\s*$/, '')};`;
}

export function stripLeadingComments(stmt: string): string {
  let s = stmt;
  for (;;) {
    const t = s.replace(/^\s+/, '');
    if (t.startsWith('--')) {
      const nl = t.indexOf('\n');
      s = nl === -1 ? '' : t.slice(nl + 1);
      continue;
    }
    if (t.startsWith('/*')) {
      const end = t.indexOf('*/');
      s = end === -1 ? '' : t.slice(end + 2);
      continue;
    }
    return t;
  }
}
